import type { Career, CareerPath } from "./types";
import { GENERAL_CAREERS, GENERAL_PATHS } from "./data-general";
import { NICHE_CAREERS, NICHE_PATHS } from "./data-niche";
import generated from "./generated/onet.json";

// Generated by `npm run data:import` from O*NET + BLS (see scripts/import-careers.mts)
const ONET = generated as unknown as {
  meta: { generatedAt: string; onetVersion: string; blsTable: string };
  paths: CareerPath[];
  careers: Career[];
  stats: Record<string, { pay: number; growth: number; employment: number; oohUrl?: string }>;
};

// Curated careers keep their hand-written content but take the latest official pay & growth
function withLatestStats(c: Career): Career {
  const s = ONET.stats[c.soc];
  return s ? { ...c, pay: s.pay, growth: s.growth, oohUrl: c.oohUrl ?? s.oohUrl } : c;
}

export const PATHS: CareerPath[] = [...NICHE_PATHS, ...GENERAL_PATHS, ...ONET.paths];
export const CAREERS: Career[] = [...NICHE_CAREERS, ...GENERAL_CAREERS].map(withLatestStats).concat(ONET.careers);

export const DATA_SOURCES = ONET.meta;

export const PATH_BY_ID = new Map(PATHS.map((p) => [p.id, p]));
export const CAREER_BY_ID = new Map(CAREERS.map((c) => [c.id, c]));
